/**
 * /contact/ —— 联系方式
 *
 * 🔴 **不得虚构联系渠道**：本页只列**真实存在**的入口 ——
 *    客服邮箱（`SUPPORT_EMAIL`，与 cart 侧同一地址，`MEMORY-cart.md` 记为唯一入口）
 *    与 Shopify App Store 的 Cart 列表页。**不写电话、不写实体地址**：
 *    这两样我们没有对外公布的值，编一个比不写更糟。
 *
 * 🔴 `softwareApp={false}`：本页不属于 Whaleal Cart 这个 Shopify 应用。
 *
 * @author 恒哥
 * @since 2026-10-12
 */
import React from 'react';
import { Link } from 'gatsby';
import Layout from '../components/Layout';
import SEO from '../components/SEO';
import {
  COMPANY_NAME,
  SUPPORT_EMAIL,
  SHOPIFY_APP_STORE_URL,
  DOCS_URL,
} from '../constants/brand';
import '../styles/marketing.css';
import T from '../i18n/LocalizedText';
import { usePageI18n } from '../i18n';

export default function ContactPage(pageContext) {
  const { locale, localePath } = usePageI18n(pageContext);

  return (
    <Layout locale={pageContext?.locale}>
      <SEO
        title="Contact Whaleal — support and partnerships"
        description={`How to reach ${COMPANY_NAME}: support by email for existing customers, and the same address for integration, security and partnership questions.`}
        pathname="/contact/"
        softwareApp={false} hrefLang={locale}
      />
      <div className="mk">
        <header className="mk-hero">
          <span className="mk-eyebrow"><T id="contact.001">Contact</T></span>
          <h1><T id="contact.002">Reach a person, not a form</T></h1>
          <p className="mk-lead">
            <T id="contact.003">{COMPANY_NAME} is a small team. Email goes to the people who build the products, and it
            is the fastest route for every kind of question we get.
          </T></p>
        </header>

        <section className="mk-section">
          <h2><T id="contact.004">Support and general questions</T></h2>
          <p className="mk-section-lead"><T id="contact.005">
            One address for existing customers, evaluations, integration questions and anything
            security-related. Include the account or shop you are asking about and we can look at the
            actual records rather than guessing.
          </T></p>
          <p className="mk-actions">
            <a className="mk-btn mk-btn-primary" href={`mailto:${SUPPORT_EMAIL}`}>
              {SUPPORT_EMAIL}
            </a>
          </p>
        </section>

        <section className="mk-section">
          <h2><T id="contact.006">Self-serve starting points</T></h2>
          <div className="mk-grid">
            <article className="mk-card">
              <h3><T id="contact.007">Whaleal Cart</T></h3>
              <p><T id="contact.008">
                Install from the Shopify App Store, or read the pricing and recovery-email pages
                first. Existing customers can find answers in the help center.
              </T></p>
              <a
                className="mk-card-link"
                href={SHOPIFY_APP_STORE_URL}
                target="_blank"
                rel="noopener noreferrer"
              ><T id="contact.009">
                Shopify App Store &rarr;
              </T></a>
            </article>
            <article className="mk-card">
              <h3><T id="contact.010">Whaleal Platform</T></h3>
              <p><T id="contact.011">
                Provider integrations, the bring-your-own-account model, pricing and the guides on
                how the channel behaves in practice.
              </T></p>
              <Link className="mk-card-link" to={localePath("/platform/")}><T id="contact.012">
                Read about Platform &rarr;
              </T></Link>
            </article>
            <article className="mk-card">
              <h3><T id="contact.013">Technical documentation</T></h3>
              <p><T id="contact.014">
                API reference and integration detail live in the docs center, separate from this
                site.
              </T></p>
              <a
                className="mk-card-link"
                href={DOCS_URL}
                target="_blank"
                rel="noopener noreferrer"
              ><T id="contact.015">
                Open the docs &rarr;
              </T></a>
            </article>
          </div>
        </section>

        <div className="mk-scope">
          <T id="contact.016"><strong>About response times.</strong> We do not publish a service-level commitment for
          email. Existing customers with a live issue should say so in the subject line &mdash; those
          go to the front.
        </T></div>
      </div>
    </Layout>
  );
}
